// Qwen-Image 2.1's steps: what its slider shows for a prop that has none saved (the hub's default for a new
// prop is the same number: projects.py, adapters/qwen.py), and the number Qwen's own reference sampling
// uses, which the slider's hint names. 25 is ComfyUI's official template for the model, checked against
// Qwen's 40 on 2026-10-03 (4 prompts at the same seed each, RTX 3060 12 GB): both were sharp and natural and
// close to each other, so 25 stays the default and 40 stays on the slider.
export const QWEN_STEPS = 25;
export const QWEN_REFERENCE_STEPS = 40;
export const QWEN_STEPS_HINT = `${QWEN_STEPS} suits most pictures; Qwen’s own reference is ${QWEN_REFERENCE_STEPS} `
  + '(slower, sometimes finer detail).';

// The built-in image generator's models, a choice per prop (images.settings.qwen_model, projects.py QWEN_MODELS):
// Qwen-Image 2.1 Turbo (the default, the one the installer downloads; its own fixed 8 steps), the full Qwen-Image 2.1
// (25 steps by default, the First-Block Cache tick) and FLUX.3 Image Klein (Black Forest Labs, drawn by the same
// engine; 16 steps, opaque pictures, its own licence). Each hides the controls it has no use for (MODEL_HIDES). The
// full model and FLUX.3 are downloads of their own (OPTIONAL_MODELS, optionalModelState); FLUX.3 also needs an image
// engine that can draw it. The label's second line is the steps: the full model's follows its slider.
export const QWEN_MODELS = [
  {
    value: 'turbo', label: 'Turbo\n(fast, 8 steps)',
    title: 'Qwen-Image 2.1 Turbo: a picture in 8 steps instead of 25, about twice as fast. Steps and Faster drawing '
      + 'are built into it.',
  },
  {
    value: 'full', label: 'Full\n(25 steps)',
    title: 'The full Qwen-Image 2.1 at the steps set under More (25 by default): slower, sometimes finer detail.',
  },
  {
    value: 'flux3', label: 'FLUX.3 Klein\n(16 steps)',
    title: 'FLUX.3 Image Klein by Black Forest Labs: 16 steps. It follows long, descriptive prompts best. Its pictures '
      + 'come with a background, which the 3D step removes.',
  },
];
export const DEFAULT_QWEN_MODEL = 'turbo';
// The controls a model hides: the Turbo and FLUX.3 have their own steps and no First-Block Cache; FLUX.3 draws no
// alpha channel, so no transparent background either.
const MODEL_HIDES = {
  full: [], turbo: ['qwenSteps', 'firstBlockCache'], flux3: ['qwenSteps', 'firstBlockCache', 'transparent', 'tileable'],
};
// The models that are a download of their own: their key in /api/status, their folder, and how the words name them.
export const OPTIONAL_MODELS = {
  full: { status: 'qwen_full', folder: 'models\\qwen-image', what: 'The full model', short: 'Full' },
  flux3: { status: 'flux3', folder: 'models\\flux3-klein', what: 'FLUX.3 Klein', short: 'FLUX.3 Klein' },
};
export const FLUX3_NEEDS_ENGINE = 'FLUX.3 Image Klein needs the next update of Spellcast3D’s image engine; it can be '
  + 'picked then.';

/** The model a prop's images settings pick: 'full' or 'flux3', else the Turbo (also for a prop from before). */
export const qwenModelOf = (settings) => (OPTIONAL_MODELS[settings?.qwen_model] ? settings.qwen_model
  : DEFAULT_QWEN_MODEL);

/** The names of the controls the image generator `tool` shows for a prop set to `model` (CONTROLS, less what that
 * model has no use for: MODEL_HIDES). */
export function shownControls(tool, model) {
  const shown = controlsOf(tool);
  if (tool === 'qwen') for (const name of MODEL_HIDES[model] || MODEL_HIDES.turbo) shown.delete(name);
  return shown;
}

const gb = (bytes) => `${(bytes / 1e9).toFixed(1)} GB`;

/**
 * An optional model (`model`: OPTIONAL_MODELS) as /api/status says ({available, downloading, waiting, done_bytes,
 * total_bytes, error}, and FLUX.3's "engine"): {state: 'unknown' (no word from the hub yet: it can be picked, and the
 * hub says if it is missing) | 'unsupported' (the image engine cannot draw it yet) | 'available' | 'missing' |
 * 'downloading' (also while it waits for the installer to finish with its folder) | 'failed', fraction (0..1 or null),
 * note: the words under its name on its button, title: its tooltip}.
 */
export function optionalModelState(model, status) {
  const meta = OPTIONAL_MODELS[model];
  const base = QWEN_MODELS.find((m) => m.value === model).title;
  if (status && typeof status === 'object' && status.engine === false) {
    return { state: 'unsupported', fraction: null, note: 'Next update', title: FLUX3_NEEDS_ENGINE };
  }
  if (!status || typeof status !== 'object' || !status.total_bytes) {
    return { state: 'unknown', fraction: null, note: '', title: base };
  }
  if (status.available) return { state: 'available', fraction: 1, note: '', title: base };
  const size = gb(status.total_bytes);
  const fraction = Math.min(1, Math.max(0, (status.done_bytes || 0) / status.total_bytes));
  const later = `Turbo works meanwhile; ${meta.short} can be picked once it is there.`;
  if (status.downloading && status.waiting) {
    return {
      state: 'downloading', fraction, note: 'Waiting for the installer…',
      title: `${meta.what} (${size}) downloads once Spellcast3D’s installer has finished with ${meta.folder}. ${later}`,
    };
  }
  if (status.downloading) {
    return {
      state: 'downloading', fraction, note: `Downloading… ${Math.round(fraction * 100)}%`,
      title: `${gb(status.done_bytes || 0)} of ${size} into ${meta.folder}. ${later}`,
    };
  }
  const started = (status.done_bytes || 0) > 0;
  if (status.error) {
    return { state: 'failed', fraction: started ? fraction : null, note: 'Try again', title: status.error };
  }
  return {
    state: 'missing', fraction: started ? fraction : null,
    note: started ? `Continue (${Math.round(fraction * 100)}%)` : `Download ${size}`,
    title: `${meta.what} is a one-time ${size} download into ${meta.folder} (the folder opens). ${later}`,
  };
}

// The controls each image generator has; the others are hidden. Both: the words (sent as they are typed),
// the shape, variations and the seed. Forge Neo: what to avoid (its negative prompt), its model list (with Add
// models…), its own steps, guidance, sampler and scheduler, and one example with how closely to follow it.
// Qwen-Image 2.1 (built in): its name with its licence chip (FLUX.3's while that is picked), the choice of its models
// (QWEN_MODELS), the resolution (RESOLUTIONS), "Faster image generation" (the hub's, for every prop), its own steps
// (QWEN_STEPS) and "Faster drawing" (the full model's only: shownControls), transparent backgrounds (not with FLUX.3)
// and up to 10 example pictures. It has no "Avoid" and no
// guidance: it is sampled the way Qwen means it to be, without guidance, and then a negative prompt is never
// read (the hub sends none). The words a prop has saved there stay with it, for Forge Neo. No image generator
// (spellcast3d-config.ini has a mistake): the shared ones, and the example pictures laid out as for the
// default one (Qwen-Image 2.1).
const SHARED = ['prompt', 'shape', 'variations', 'seed'];
export const CONTROLS = {
  forge: [...SHARED, 'avoid', 'model', 'steps', 'cfg', 'sampler', 'example', 'follow'],
  qwen: [...SHARED, 'tool', 'qwenModel', 'resolution', 'qwenSteps', 'transparent', 'tileable', 'firstBlockCache',
    'fastImages', 'examples'],
};
const NO_GENERATOR = [...SHARED, 'examples'];
const MAX_SEED = 2 ** 32 - 1;                  // both image generators take seeds up to this (adapters/qwen.py)

/** The names of the controls the image generator `tool` shows (CONTROLS). */
export const controlsOf = (tool) => new Set(CONTROLS[tool] || NO_GENERATOR);

/**
 * A prop's example pictures, in the order they are given to the image generator (images.references); a
 * prop from before there could be several: its one example (images.reference).
 */
export function refsOf(images) {
  if (Array.isArray(images?.references)) return images.references.filter((r) => typeof r === 'string' && r);
  return images?.reference ? [images.reference] : [];
}

/**
 * Of `files` dropped or chosen as example pictures for a prop that has `count` already: the ones that fit
 * (up to MAX_REFS in all, the first ones) and how many are left out.
 */
export function refsToAdd(count, files) {
  const take = files.slice(0, Math.max(0, MAX_REFS - count));
  return { take, left: files.length - take.length };
}

/** The pictures on the clipboard as files, for "Paste (Ctrl+V)" (the browser may ask to allow it); none: []. */
async function clipboardImages() {
  const files = [];
  for (const item of await readClipboardItems()) {
    const type = item.types.find((t) => t.startsWith('image/'));
    if (type) files.push(new File([await item.getType(type)], `pasted.${type.split('/')[1]}`, { type }));
  }
  return files;
}

/**
 * The live preview to show for a prop whose images job is `j` (store.jobFor), while `shown` shows (its address,
 * '' for none): the newest one the job has (progress.preview.url: a low-res picture of what Qwen-Image 2.1 is
 * drawing, at a new address after every step). Between two pictures of a batch the job has none for a moment:
 * the one shown stays. '' as soon as the job is not drawing this prop's pictures (it finished, failed, was
 * stopped, still waits, or went on to another prop). With `propId`, a preview of another prop (progress.preview.prop:
 * the one on the card, while this prop still works behind it) is not this prop's: the one shown stays.
 */
export function livePreview(j, shown = '', propId = '') {
  if (j?.phase !== 'running') return '';
  const preview = j.job?.progress?.preview;
  if (propId && preview?.prop && preview.prop !== propId) return shown;
  const url = preview?.url;
  return typeof url === 'string' && url ? url : shown;
}

/**
 * Where on the picture the job `j`'s newest preview lies, when it is of a part of it (progress.preview.box: the window
 * a masked change is drawn in, [left, top, right, bottom] as fractions of the picture as the page shows it; on a
 * tileable picture right and bottom may pass 1); null: it is of all of the picture.
 */
export function previewBox(j) {
  const box = j?.job?.progress?.preview?.box;
  const ok = Array.isArray(box) && box.length === 4 && box.every(Number.isFinite) && box[2] > box[0] && box[3] > box[1];
  return ok ? box : null;
}

/**
 * A preview of the box `box` (previewBox) laid on the picture, in parts inside it - what reaches past its right or
 * bottom edge comes back at the other side -: [{part: [left, top, right, bottom] on the picture, preview: [left, top,
 * width, height] of the whole preview round that part, as fractions of the part}]. (mask_window.js windowParts lays a
 * box as long as a side along all of it, right for a frame; a window that long, moved round the edge, is cut here too.)
 */
export function previewParts(box) {
  const along = (i) => [[box[i], Math.min(box[i + 2], 1), 0], [Math.max(box[i], 1), box[i + 2], 1]]
    .filter(([low, high]) => high > low);   // [low, high, how far it comes back]
  return along(0).flatMap(([x0, x1, dx]) => along(1).map(([y0, y1, dy]) => {
    const [w, hh] = [x1 - x0, y1 - y0];
    return {
      part: [x0 - dx, y0 - dy, x1 - dx, y1 - dy],
      preview: [(box[0] - x0) / w, (box[1] - y0) / hh, (box[2] - box[0]) / w, (box[3] - box[1]) / hh],
    };
  }));
}

const pct = (fraction) => `${Math.round(fraction * 1e6) / 1e4}%`;
const boxStyle = ([left, top, width, height]) => `left: ${pct(left)}; top: ${pct(top)}; width: ${pct(width)}; `
  + `height: ${pct(height)}`;

/** The preview at `url` over the part `box` of a picture as wide as `aspect` times its height, in its fitted box. */
function previewOver(url, box, aspect) {
  const fit = h('div', { class: 'sv-live-fit' }, previewParts(box).map(({ part: [l, t, r, b], preview }) => h('div', {
    class: 'sv-live-part', style: boxStyle([l, t, r - l, b - t]),
  }, h('img', { src: url, alt: '', draggable: 'false', style: boxStyle(preview) }))));
  fit.style.setProperty('--ar', String(aspect));
  return h('div', { class: 'sv-live-area' }, fit);
}

const LIVE_LINGER_MS = 600;   // the last preview stays this long after its job: the picture itself arrives meanwhile
const MAX_UNDO = 50;          // removed pictures Ctrl+Z can bring back, per workbench
// The settings each picture remembers: the ones last set while it was the chosen picture (buildBench's remember).
const PICTURE_SETTINGS = ['prompt', 'negative_prompt', 'checkpoint', 'qwen_model', 'qwen_steps', 'steps', 'cfg_scale',
  'sampler', 'scheduler', 'batch_count', 'transparent', 'first_block_cache', 'seed', 'width', 'height', 'resolution'];
const POP_MS = 400;           // a pasted example picture pops in

/** The model's file name: "SDXL\realvisxlV50_v50Lightning.safetensors [31e35c80fc]" -> "realvisxlV50_v50Lightning.safetensors". */
const modelFile = (title) => title.replace(/\s*\[[0-9a-f]+\]$/i, '').replace(/^.*[\\/]/, '');

/** The model's name as the list shows it: "realvisxlV50_v50Lightning.safetensors" -> "realvisxlV50 v50Lightning" */
const modelLabel = (title) => modelFile(title).replace(/\.(safetensors|ckpt|gguf)$/i, '').replace(/[_-]+/g, ' ').trim();

const modes = new Map();      // prop id -> the mode picked for it in this page
let host = null;
let root = null;              // the workbench's frame: the chooser or a prop's workbench inside it
let ctx = null;               // the newest context the shell handed over
let screen = null;            // what the frame shows: {id, kind: 'chooser' | 'bench', draft, el, update, nudge, destroy}
let adopting = null;          // the prop the draft on screen has just become, until the shell has selected it
let lastShown = null;         // the prop shown here last: coming back to Images shows it again

/**
 * The mode a prop opens in: the one picked for it in this page; else Use Existing Images when a picture without
 * words was imported; else Render Images.
 */
export function modeOf(prop) {
  if (modes.has(prop.id)) return modes.get(prop.id);
  const img = prop.images || {};
  if (refsOf(img).length) return 'example';
  if (img.chosen && !img.settings?.prompt?.trim()) return 'import';
  return 'example';
}

/**
 * Render Images picked for a prop saved with its example pictures left out (images.settings.use_references false,
 * from an older version): they go along again from here on.
 */
function saveMode(id, mode) {
  if (mode !== 'import' && getProp(id)?.images?.settings?.use_references === false) {
    queueSettings(id, 'images', { use_references: true });
  }
}

/** A draft with nothing in it yet, and no way picked for it: it offers the ways. */
const choosing = (p) => !!p.draft && !modes.has(p.id) && !p.images?.chosen && !refsOf(p.images).length
  && !p.images?.candidates?.length && !p.images?.settings?.prompt?.trim() && !jobFor('images', p.id);

/**
 * The prop the workbench shows: the one selected in the props column; else the one the draft on screen
 * has just become (it stays, and render() selects it); else the draft.
 */
function boundProp() {
  if (adopting && ctx?.selectedId === adopting) adopting = null;   // selected by now
  return findBox(ctx?.selectedId) || findBox(adopting) || (screen?.draft ? findBox(screen.id) : null) || draftOf();
}

/**
 * The prop Images opens on: the draft when it has words or an example; else the prop selected in
 * the column, the one shown here last, or the last prop; else the empty draft (null).
 */
function entryId(c) {
  const d = draftOf();
  if (d && (d.images?.settings?.prompt?.trim() || refsOf(d.images).length)) return null;
  return (findBox(c.selectedId) || findBox(lastShown) || boxesOf().at(-1))?.id ?? null;
}

/**
 * What Images asks the hub to have ready (the view's warmWish: shell.js asks as Images shows): the image generator
 * spellcast3d-config.ini picks, loading the model the prop on screen draws with, in Images' arithmetic (faster.js),
 * and taking the card from a tool that idles on it - the artist came for pictures. The hub never does so beside a job.
 */
function warmWish(model = qwenModelOf(boundProp()?.images?.settings)) {
  const tool = imageTool();
  return tool ? { tool, displace: true, ...(tool === 'qwen' ? { model, stage: 'images' } : {}) } : null;
}

/** The artist picked another model: the hub loads it now, in place of one that is still loading. */
function warmPicked(model) {
  const ask = warmAsk(store.status?.tools, warmWish(model));
  if (ask) warmTool(ask.tool, ask.wish);
}

/** Forge's model list, once Forge answers (the list is kept while Forge is off); Forge Neo only. */
function wantModels() {
  if (imageTool() !== 'forge') return;
  if (['unknown', 'offline'].includes(store.models?.state) && ['ready', 'busy'].includes(toolStatus('forge')?.state)) loadModels();
}

/** A short ring around `el`, `times` over: this is where to start, or this has just changed. */
function pulse(el, times = 1) {
  el?.animate([
    { boxShadow: '0 0 0 0 rgba(139, 125, 255, 0.6)' },
    { boxShadow: '0 0 0 7px rgba(139, 125, 255, 0)' },
  ], { duration: 700, easing: 'ease-out', iterations: times });
}

// ---- the chooser of an empty draft -------------------------------------------------------------

// The chooser's own fifth card: a folder of several props' pictures. The hub opens the folder picker (a native
// dialog: the browser's own would upload every file through the page, with Edge's "Upload from mobile" button in
// it) and reads the folder itself (spellcast/propfiles.py; the page's propfiles.js has the same rules for a drop).
// Not a way of one prop, so it is no tab of the workbench.
const FOLDER_CARD = {
  choice: 'Import folder (multiple prop images)', icon: 'folder',
  text: 'Batch-imports different props’ images from a folder.\nImage names need a _front, _back, _left, _right '
    + 'suffix, or a front_, back_, left_, right_ prefix.',
};

/**
 * Big cards, one per way to the picture, in one row ("Use Existing Images", "Render Images"), and under them
 * the wide "Import folder" button, two cards long. Images dropped anywhere on it are imported: the sides of one
 * prop, or, when their names say so (knight_front, knight_back, dragon_front...), of several props at once
 * (importProps).
 */
function buildChooser(prop) {
  let picked = false;
  const card = (choice, text, iconName, onclick) => h('button', { type: 'button', class: 'sv-choice', onclick },
    h('span', { class: 'sv-choice-body' },
      h('span', { class: 'sv-choice-icon' }, icon(iconName)),
      h('b', null, choice),
      h('span', { class: 'sv-choice-text' }, text)));
  const cards = modesFor(imageTool()).map((m) => card(m.choice, m.text, m.icon, () => pick(m.value)));
  // The folder button: its icon beside its words, two cards wide and a third as tall.
  const folder = h('button', { type: 'button', class: 'sv-choice sv-choice-folder', onclick: () => importFolder() },
    h('span', { class: 'sv-choice-body' },
      h('span', { class: 'sv-choice-icon' }, icon(FOLDER_CARD.icon)),
      h('span', { class: 'sv-choice-words' },
        h('b', null, FOLDER_CARD.choice),
        h('span', { class: 'sv-choice-text' }, FOLDER_CARD.text))));
  const rows = [
    h('div', { class: 'sv-choices' }, cards),
    h('div', { class: 'sv-choices' }, folder),
  ];
  const title = h('h3', { class: 'sv-chooser-title' }, boxesOf().length ? 'New prop' : 'Your first prop');
  const drop = h('p', { class: 'sv-chooser-drop' }, icon('upload'), 'Or drop images anywhere here, or paste one with Ctrl+V');
  // The first start: the image generator may still be downloading (11 GB). Said once, quietly, with how far.
  const note = h('p', { class: 'sv-chooser-note', hidden: true });
  const syncNote = () => {
    const gate = toolGate('images');
    note.hidden = gate.kind !== 'installing';
    if (!note.hidden) {
      note.textContent = `Render Images needs ${toolName(imageTool())}, still installing`
        + `${gate.bytes ? ` (${gate.bytes.replace(/^ · /, '')})` : ''}. Use Existing Images works now.`;
    }
  };
  syncNote();
  // Where a prop begins: the lessons and the community in the corner (Donate comes with the work, further on).
  const corner = [lessonsCorner(), discordCorner()];
  const el = h('div', { class: 'sv-chooser' }, title, h('div', { class: 'sv-choice-rows' }, rows), drop, note, corner);
  dropTarget(el, (files) => (severalProps(files) ? importProps(files) : pick('import', files)),
    () => toast(NOT_AN_IMAGE, 'warn'), { all: true });
  // Ctrl+V: a copied picture becomes the prop's picture, as if it had been dropped. With the text cursor in a field
  // the paste is the field's own.
  const onPaste = (e) => {
    if (picked || screen !== self || dialogOpen() || isTextField()) return;
    const files = [...(e.clipboardData?.files || [])].filter((f) => f.type.startsWith('image/'));
    if (!files.length) return;
    e.preventDefault();
    pick('import', files);
  };
  document.addEventListener('paste', onPaste);

  /**
   * "Import folder": the hub's folder picker, then the hub reads the folder (its subfolders too) and makes the props
   * (POST .../import-folder); the first new prop is selected and a toast says what was made.
   */
  async function importFolder() {
    if (picked || screen !== self) return;
    picked = true;
    folder.disabled = true;
    try {
      const chosen = await attempt(() => api('POST', '/api/pick-folder'));
      if (!chosen?.folder) return;
      const made = await attempt(() => api('POST', `${projectApi(projectId())}/import-folder`, { folder: chosen.folder }));
      if (!made) return;
      await attempt(() => reloadProject());
      if (made.props?.length) ctx?.select(made.props[0].id);
      const said = (made.props || []).map((m) => `${m.name}${m.sides?.length ? ` (${m.sides.map((v) => VIEWS[v].short).join(', ')})` : ''}`);
      toast([
        made.props?.length ? `Imported ${plural(made.props.length, 'prop')}: ${said.join(' · ')}.` : 'No prop was imported.',
        made.skipped?.length ? `Left out ${made.skipped.join('; ')}.` : '',
      ].filter(Boolean).join(' '), made.skipped?.length ? 'warn' : 'success', 12000);
    } finally {
      picked = false;
      folder.disabled = false;
    }
  }

  /**
   * One prop per group of `files` (propfiles.groupPropFiles): each is made, then its pictures are uploaded as its
   * sides (the front one chosen), prop after prop, with a toast at the end. The draft stays as it is (it is still
   * the next, empty prop); the first new prop is selected.
   */
  async function importProps(files) {
    if (picked || screen !== self) return;
    const groups = groupPropFiles(files);
    picked = true;   // no card is taken meanwhile
    folder.disabled = true;
    const made = [];
    const failed = [];
    const skipped = [];
    try {
      for (const g of groups) {
        const own = g.files.slice(0, MAX_IMPORT);
        if (g.files.length > MAX_IMPORT) skipped.push(`${g.name}: ${g.files.length - MAX_IMPORT} more than ${MAX_IMPORT}`);
        const sides = own.some((f) => f.side) ? own.map((f) => f.side) : null;
        try {
          const fresh = await addProp(g.name);
          await uploadImages(fresh.id, own.map((f) => f.file), null, own.length > 1 ? sides : null);
          made.push({ id: fresh.id, name: g.name, sides: own.map((f) => f.side).filter(Boolean) });
        } catch (e) {
          console.warn(e);
          failed.push(`${g.name}: ${e?.message || e}`);
        }
      }
    } finally {
      picked = false;
      folder.disabled = false;
    }
    if (made.length) {
      await attempt(() => reloadProject());
      ctx?.select(made[0].id);
    }
    const said = made.map((m) => `${m.name}${m.sides.length ? ` (${m.sides.map((v) => VIEWS[v].short).join(', ')})` : ''}`);
    const kind = failed.length ? 'warn' : 'success';
    toast([
      made.length ? `Imported ${plural(made.length, 'prop')}: ${said.join(' · ')}.` : 'No prop was imported.',
      failed.length ? `Could not import ${failed.join('; ')}.` : '',
      skipped.length ? `Left out ${skipped.join('; ')}.` : '',
    ].filter(Boolean).join(' '), kind, 12000);
  }

  /** The way `mode` is picked: the cards turn into the workbench (dropped `files` are imported at once). */
  async function pick(mode, files = null) {
    if (picked || screen !== self) return;
    picked = true;
    cards[MODES.findIndex((m) => m.value === mode)].classList.add('on');
    modes.set(prop.id, mode);
    saveMode(prop.id, mode);
    const next = buildBench(getProp(prop.id) || prop);
    if (files) next.importImages(files);
    await morph(self, next);
    if (!files && screen === next) next.begin();
  }

  const self = {
    id: prop.id, kind: 'chooser', draft: true, el, cards, extras: [title, folder, drop, note, ...corner],
    update(p) {
      self.draft = p.draft;
      syncNote();
    },
    /** "+ New prop" while it shows: the cards say "here". */
    nudge() {
      const full = fullMotion();
      cards.forEach((card, i) => {
        if (full) {
          card.animate([{ transform: 'none' }, { transform: 'scale(1.05)', offset: 0.4 }, { transform: 'none' }],
            { duration: 420, delay: i * 70, easing: 'ease-out' });
        } else {
          pulse(card);
        }
      });
    },
    destroy() {
      document.removeEventListener('paste', onPaste);
    },
  };
  return self;
}

/**
 * The chooser's cards fly to the mode control of `next` (the new workbench) and become its buttons: a
 * FLIP of transform and opacity, while the picture and the controls fade in around them.
 * Gentle motion: a short cross-fade. `next` is on screen from the start (renders go to it).
 */
async function morph(chooser, next) {
  chooser.el.classList.add('leaving');   // no hover lift, no clicks: measured as laid out
  const from = chooser.cards.map((c) => c.getBoundingClientRect());
  screen = next;
  root.prepend(next.el);   // under the chooser
  const anims = [];
  if (fullMotion()) {
    const to = next.modeButtons.map((b) => b.getBoundingClientRect());
    chooser.cards.forEach((card, i) => {
      const [f, t] = [from[i], to[i]];
      if (!f.width || !t?.width) return;
      const flown = `translate(${t.left - f.left}px, ${t.top - f.top}px) scale(${t.width / f.width}, ${t.height / f.height})`;
      // The flight eases in and out; the card dissolves into its button only once it is (nearly) there.
      anims.push(
        card.animate([
          { transform: 'none', opacity: 1, easing: MORPH_EASE }, { opacity: 1, offset: 0.85 }, { transform: flown, opacity: 0 },
        ], { duration: MORPH_MS, fill: 'forwards' }),
        card.firstChild.animate([{ opacity: 1 }, { opacity: 0, offset: 0.25 }, { opacity: 0 }], { duration: MORPH_MS, fill: 'forwards' }),
      );
    });
    for (const el of chooser.extras) anims.push(el.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 140, fill: 'forwards' }));
    anims.push(
      next.modeSeg.animate([{ opacity: 0 }, { opacity: 0, offset: 0.7 }, { opacity: 1 }], { duration: MORPH_MS }),
      ...next.body.map((el) => el.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 300, delay: 140, easing: 'ease-out', fill: 'backwards' })),
    );
  } else {
    anims.push(
      chooser.el.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 150, fill: 'forwards' }),
      next.el.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 150 }),
    );
  }
  await settle(anims, MORPH_MS + 600);
  chooser.el.remove();
  chooser.destroy();
}

/** The picture at `url` turned a quarter clockwise, every pixel as it is -> {png: a Blob, width, height: as turned}. */
async function quarterTurned(url) {
  const got = await fetch(url);
  if (!got.ok) throw new Error('That picture could not be read. Reload the page and try again.');
  const bitmap = await createImageBitmap(await got.blob());
  const canvas = Object.assign(document.createElement('canvas'), { width: bitmap.height, height: bitmap.width });
  const g = canvas.getContext('2d');
  g.imageSmoothingEnabled = false;
  g.setTransform(0, 1, -1, 0, canvas.width, 0);
  g.drawImage(bitmap, 0, 0);
  bitmap.close?.();
  const png = await new Promise((resolve) => { canvas.toBlob(resolve, 'image/png'); });
  if (!png) throw new Error('The picture could not be turned.');
  return { png, width: canvas.width, height: canvas.height };
}

// ---- the workbench of a prop ------------------------------------------------------------------

function buildBench(prop) {
  const id = prop.id;
  const cur = () => getProp(id) || prop;
  const settings = () => cur().images?.settings || {};
  const set = (patch) => queueSettings(id, 'images', patch);
  const s = settings();
  let mode = modeOf(prop);
  let backend;   // the image generator the controls are shown for (syncBackend)

  // ---- top: the picture's tools above the picture, the mode above the controls ------------------------
  const modeSeg = segmented(modesFor(imageTool()), mode, (v) => {
    setMode(v);
    saveMode(id, v);
    if (v !== 'import' && !prompt.value) prompt.focus({ preventScroll: true });
  });
  modeSeg.classList.add('sv-modes');
  modeSeg.setAttribute('aria-label', 'How the picture is made');
  // Left of it: the tools of the picture (the slicer mounts its buttons here), centred above the picture; the
  // ones that do not fit in a row there wrap into centred rows, and the header grows (stages-images.css).
  const slicerTools = h('div', { class: 'sv-tools-part' });
  const toolsEl = h('div', { class: 'sv-tools' }, slicerTools);
  const head = h('header', { class: 'sv-imghead' }, toolsEl, modeSeg);

  // ---- left: the picture, and under it the prop's pictures in a row (the newest on the right) ----------
  const picture = h('div', { class: 'sv-picture' });
  const busy = busyLayer('images');

  // What Ctrl+Z takes back here, the newest last, each stamped `at` (undo.js: the slicer's changes and the props
  // column's deletions take their turns by the same stamps): {kind: 'remove', path, index, views, chosen} - a picture
  // removed with its × comes back to its place, with the views it had, chosen again if it was -, {kind: 'mark', path,
  // after} and {kind: 'examples', refs, after}. `after`: the views' signature when the change was made; a mark or
  // example pictures are undone only while the views are still so.
  const done = [];
  const dropUndo = undoList(() => done.at(-1)?.at);
  const viewsNow = () => viewsSignature(cur().images?.views || []);
  const lastRemoval = () => done.findLast((d) => d.kind === 'remove');
  const bringBack = () => {
    if (leaving.size) {   // a removal still on its way to the hub comes back once it is through
      removals = removals.then(() => lastRemoval() && bringBack());
      return;
    }
    const back = lastRemoval();
    done.splice(done.indexOf(back), 1);
    return attempt(() => restoreImage(id, back.path, back));
  };
  /** The newest mark on the picture shown or the example pictures added last (Render Images), else the last removal. */
  function onUndo(e) {
    if (!isUndoKey(e) || screen !== self || dialogOpen() || isTextField()) return;
    if (mode === 'example') {
      for (let last = done.at(-1); last && last.kind !== 'remove' && last.after === viewsNow() && isNewest(last.at);
        last = done.at(-1)) {
        if (last.kind === 'mark') {
          if (last.path !== marks.path) break;   // painted on another picture: it waits
          done.pop();
          if (!marks.undo()) continue;
        } else {
          done.pop();
          const there = last.refs.filter((r) => refsOf(cur().images).includes(r));
          if (!there.length) continue;   // gone meanwhile
          attempt(async () => { for (const r of there) await removeReferences(id, r); });
        }
        e.preventDefault();
        e.stopImmediatePropagation();
        return;
      }
    }
    const back = lastRemoval();
    if (!leaving.size && !(back && isNewest(back.at))) return;
    e.preventDefault();
    e.stopImmediatePropagation();
    bringBack();
  }
  document.addEventListener('keydown', onUndo, true);

  /**
   * The × of a picture (its `tile` in the row): it leaves the row at once (tilerow.js) and the prop when the hub has
   * it. The hub is told one removal after another, each as the one before left the pictures, so Ctrl+Z puts each
   * back at its place. A removal the hub refuses brings the tile back.
   */
  const leaving = new Set();   // pictures on their way out
  let removals = Promise.resolve();
  function removePicture(path, tile) {
    if (leaving.has(path) || !cur().images?.candidates?.includes(path)) return;
    tileRow.removing(tile);
    leaving.add(path);
    renderStrip(cur());
    removals = removals.then(async () => {
      const img = cur().images || {};
      const entry = {
        kind: 'remove', path, index: img.candidates?.indexOf(path) ?? -1,
        views: (img.views || []).filter((v) => v.src === path), chosen: img.chosen === path,
      };
      const gone = entry.index >= 0 && await attempt(() => removeImage(id, path).then(() => true));
      leaving.delete(path);
      if (!gone) {
        shownStrip = null;
        renderStrip(cur());
        return;
      }
      done.push({ ...entry, at: undoStamp() });
      const kept = done.filter((d) => d.kind === 'remove');
      if (kept.length > MAX_UNDO) done.splice(done.indexOf(kept[0]), 1);
    });
  }

  // The markers over the picture (marks.js), under the slicer's layer: while slicing, a drag draws a slice; elsewhere
  // it paints. Both are layers next to the picture, so a re-render of the picture keeps them.
  const marks = createMarks({
    onStroke: (path) => done.push({ kind: 'mark', path, after: viewsNow(), at: undoStamp() }),
    onSelect: (object, picture) => {
      circling = object;
      generate('viewport', { prompt: circled(object), picture });
    },
    // A mask on the picture: Re-Render Viewport changes what it covers (From Scratch waits); each stroke let go
    // points at the words that say what becomes of it - far from the mask, so a ripple that reaches far.
    onMask: (brushed) => {
      syncFoot();
      if (brushed) ripple(promptBox);
    },
    onTool: () => slicer.stop(),   // a marker or a tool taken up: the presses on the picture are its, not slices
    maskRequest: () => maskRequest(),
  });
  /**
   * The picture a Smart Mask job asks for (generate): the Shape at the Resolution, tileable or not - {width, height,
   * tileable}; null on the black canvas, which is sent without a mask and drawn anew, all of it.
   */
  function maskRequest() {
    if (!cur().images?.chosen) return null;
    const now = settings();
    const factor = controlsOf(backend).has('resolution') ? now.resolution || 1 : 1;
    const [width, height] = sizeAt(`${now.width || 1024}x${now.height || 1024}`, factor);
    return { width, height, tileable: tilingOn() };
  }
  const slicer = createSlicer(id, { toolbar: slicerTools, onSave: saveShown });

  /** "Save": the picture the viewport shows, with the marks painted on it, into the prop's export folder. */
  async function saveShown() {
    const png = await marks.composite();
    const path = png ? await saveViewport(id, png) : cur().images?.chosen;
    if (!path) return false;
    const answer = await savePicture(id, path);
    toastSaved(answer?.shown || 'the picture', answer);
    return true;
  }
  // While imported pictures go up (a big upload takes a moment): how far it got. Two imports at once share
  // it: it stays until the last one is up.
  let uploads = 0;
  const uploadText = h('div', { class: 'sv-busy-text' });
  const uploadBar = progressBar(null);
  const uploading = h('div', { class: 'sv-busy', hidden: true, role: 'status' }, spinner(), uploadText, uploadBar);
  // While Qwen-Image 2.1 makes this prop's picture: the rough preview of it, in the picture's place (or over the part
  // of it drawn in a window), under the progress (which steps down to the bottom edge: stages-images.css).
  const live = h('div', { class: 'sv-live', hidden: true }, h('span', { class: 'sv-live-tag' }, 'Rough preview'));
  // The prompt library over the viewport while open ("+prompt" under the words: promptlib.js).
  const library = libraryPanel();
  // An example picture under the pointer, in the viewport's top right corner (examplesList).
  const peekImg = h('img', { alt: '', draggable: 'false' });
  const peek = h('div', { class: 'sv-ref-peek', hidden: true, 'aria-hidden': 'true' }, peekImg);
  // A tileable picture looked at from afar (the wheel, zoomed all the way out): copies of it all round, under it.
  const tiling = h('div', { class: 'sv-tiling', hidden: true },
    h('div', { class: 'sv-tiling-fit' }, h('div', { class: 'sv-tiling-field' })));
  const stageEl = h('div', { class: 'sv-stagebox sv-imgstage' }, tiling, picture, marks.el, slicer.el, live, busy,
    uploading, donateCorner(), marks.hint, marks.bar, peek, library.el);
  // The wheel zooms the picture, the middle button pans it (picview.js).
  const view = createPictureView(stageEl, {
    measure: () => (picture.querySelector('.sv-picture-img')
      ? { w: picture.offsetWidth, h: picture.offsetHeight, aspect: shownAspect() } : null),
    tiles: () => !tiling.hidden,
    changed: () => syncMarks(),
  });
  dropTarget(stageEl, (files) => importImages(files), () => toast(NOT_AN_IMAGE, 'warn'), { all: true });
  let liveUrl = '';     // the preview asked for last ('' none)
  let liveImg = null;   // the one on screen: the preview, or its parts over the part of the picture it is of
  let liveGone = null;  // the timer that takes the last one away
  const hideLive = () => {
    live.hidden = true;
    stageEl.classList.remove('live');
    liveImg?.remove();
    liveImg = null;
  };
  /** The aspect ratio of the picture the viewport shows (before it has loaded: the prop's Shape's). */
  function shownAspect() {
    const shown = picture.firstChild;
    const [w, hh] = shown?.tagName === 'CANVAS' ? [shown.width, shown.height] : [shown?.naturalWidth, shown?.naturalHeight];
    return w && hh ? w / hh : (settings().width || 1024) / (settings().height || 1024);
  }
  /**
   * Shows the newest live preview (livePreview). Each one is loaded first and then swapped in: no flicker. The
   * last one stays for LIVE_LINGER_MS after the job: the picture it became is on its way (the project is read
   * again, then it loads), and the picture from before would flash up meanwhile. A preview of a part of the picture
   * (previewBox: a window of a masked change) lies over just that part, the rest of the picture in sight round it, so
   * that a change going wrong shows while it is drawn.
   */
  function renderLive() {
    const j = jobFor('images', id);
    const url = livePreview(j, liveUrl);
    if (url === liveUrl) return;
    liveUrl = url;
    clearTimeout(liveGone);
    if (!url) {
      if (liveImg) liveGone = setTimeout(hideLive, LIVE_LINGER_MS);
      else hideLive();
      return;
    }
    const box = previewBox(j);
    const next = h('img', { class: 'sv-live-img', alt: 'A rough preview of the picture being made', draggable: 'false' });
    next.onload = () => {
      if (liveUrl !== url) return;   // a newer one is on its way, or the picture is done
      const shown = box ? previewOver(url, box, shownAspect()) : next;
      if (liveImg) liveImg.replaceWith(shown);
      else live.prepend(shown);
      liveImg = shown;
      live.classList.toggle('part', !!box);
      live.hidden = false;
      stageEl.classList.add('live');
    };
    next.src = url;
  }
  const strip = h('div', { class: 'sv-cands', role: 'listbox', 'aria-label': 'Pictures made for this prop' });
  // A picture carried out of the row onto the props column becomes a prop of its own (promote); the column shows
  // where it can go.
  const propsColumn = () => document.querySelector('.props');
  const tileRow = createTileRow(strip, {
    carry: {
      over(x, y) {
        const hit = !!document.elementFromPoint?.(x, y)?.closest('.props');
        propsColumn()?.classList.add('drop-ready');
        propsColumn()?.classList.toggle('drop-here', hit);
        return hit;
      },
      end: () => propsColumn()?.classList.remove('drop-ready', 'drop-here'),
      drop: (tile) => promote(tile.getAttribute('data-path')),
    },
  });
  const media = h('div', { class: 'sv-media' }, stageEl, strip);

  /**
   * The prop's pictures under the picture, the oldest first, the chosen one marked, always as the store has them.
   * A click on a tile chooses the picture, Alt + click shows what Qwen-Image was given for it (given.js) and chooses
   * nothing; its × takes it out of the prop. New pictures scroll the row to its end; otherwise the chosen one is kept
   * in view.
   */
  let shownStrip = null;
  let shownCount = null;
  let circling = null;           // the object of the Select Object job on its way: its pictures are named after it
  const circledIn = new Map();   // a picture -> the object circled to make it (promote names its prop so)
  let candsSeen = new Set(prop.images?.candidates || []);
  let chosenSeen = prop.images?.chosen ?? null;

  // Each picture keeps the settings last set while it was the chosen one, with the project (ui.picture_settings):
  // a click on it brings them back (pick), whatever made it.
  function remember(path) {
    if (!path || !store.project?.ui) return;
    const now = settings();
    const all = store.project.ui.picture_settings || {};
    const live = new Set(cur().images?.candidates || []);
    const mine = Object.fromEntries(Object.entries(all[id] || {}).filter(([k]) => live.has(k)));
    mine[path] = Object.fromEntries(PICTURE_SETTINGS.filter((k) => k in now).map((k) => [k, now[k]]));
    updateUi({ picture_settings: { ...all, [id]: mine } });
  }
  /** A click on a picture: the one before keeps its settings, this one brings its own back. */
  function pick(path) {
    remember(chosenSeen);
    chosenSeen = path;
    // The prop's tile in the column rings: the picture picked here is the prop's from now on.
    attempt(() => selectImage(id, path)).then(() => emit('pulse-prop', { id }));
    const kept = store.project?.ui?.picture_settings?.[id]?.[path];
    if (!kept) return;
    set(kept);
    showSettings();
  }
  function renderStrip(p) {
    const img = p.images || {};
    if (img.chosen !== chosenSeen) {   // another picture is chosen: the one before keeps the settings it had
      remember(chosenSeen);
      chosenSeen = img.chosen;
    }
    const cands = (img.candidates || []).filter((c) => !leaving.has(c));
    const fresh = (img.candidates || []).filter((c) => !candsSeen.has(c));
    if (circling && fresh.length) {
      for (const c of fresh) circledIn.set(c, circling);
      circling = null;
    }
    candsSeen = new Set(img.candidates || []);
    const views = img.views || [];
    const marked = img.chosen;
    const key = `${cands.map((c) => boxFile(p, c, 'images')).join()}|${img.chosen}|${viewsSignature(views)}`;
    if (key === shownStrip) return;
    shownStrip = key;
    const first = shownCount === null;
    const grew = !first && (img.candidates || []).length > shownCount;
    shownCount = (img.candidates || []).length;
    strip.hidden = !cands.length;
    strip.replaceChildren(...cands.map((c) => {
      const say = c === marked ? 'The chosen picture' : 'Use this picture';
      const tile = h('div', {
        class: `sv-cand${c === marked ? ' on' : ''}`, role: 'option', 'aria-selected': String(c === marked),
        title: `${say}. ${INPUTS_KEY}`, 'data-path': c,
        onclick: (e) => {
          if (e.altKey) showGiven(cur(), c);
          else if (c !== cur().images?.chosen) pick(c);
        },
      },
      h('button', { type: 'button', class: 'sv-cand-pick', 'aria-label': say },
        h('img', { src: boxFile(p, c, 'images'), alt: '', loading: 'lazy', draggable: 'false' }), viewChip(views, c)),
      h('button', {
        type: 'button', class: 'sv-cand-x', title: 'Remove this picture (Ctrl+Z brings it back)', 'aria-label': 'Remove this picture',
        onclick: (e) => {
          e.stopPropagation();   // not a click on the tile: it would choose the picture on its way out
          removePicture(c, tile);
        },
      }, icon('x')));
      return tile;
    }));
    // the newest at the end of the row in view, else the chosen one (the row scrolls sideways; at first from its end)
    tileRow.reveal(grew ? strip.lastElementChild : strip.querySelector('.on') || strip.lastElementChild, { fromEnd: first });
  }

  /**
   * The picture area: the chosen picture; without one, what the mode offers instead - on Render Images a black canvas
   * of the prop's Shape, for the markers to paint on and Re-Render Viewport to make pictures from (`blank`).
   */
  let shownPicture = null;
  let blank = false;
  let shift = 0;        // a tileable picture is shown moved by this much of its size, right and down (-0.5 .. 0.5)
  function renderPicture(p) {
    const img = p.images || {};
    const src = img.chosen ? boxFile(p, img.chosen, 'images') : '';
    const [w, hh] = [settings().width || 1024, settings().height || 1024];
    stageEl.classList.toggle('has-image', !!img.chosen);
    const key = `${src}|${mode}|${thumbUrl(p, 'mesh')}|${w}x${hh}|${shift}`;
    if (key === shownPicture) return;
    shownPicture = key;
    const shown = img.chosen ? h('img', { class: 'sv-picture-img', src, alt: p.name || 'Chosen picture', draggable: 'false' }) : null;
    const own = !shown && !p.draft && p.mesh?.imported;
    blank = !shown && !own && mode === 'example';
    tiling.style.setProperty('--tile', shown ? `url("${src}")` : 'none');
    shown?.addEventListener('load', () => {
      tiling.style.setProperty('--ar', String(shown.naturalWidth / shown.naturalHeight));
      view.refit();               // its own shape now: the view keeps within reach of it
    }, { once: true });
    if (shown && shift) {
      // Shifted, the picture is a canvas of the page's: it takes the picture's place once it is drawn (the one on
      // screen stays until then), and it is what Re-Render Viewport sends, marks or none.
      shown.decode().then(() => {
        if (shownPicture !== key) return;
        const moved = shiftedCanvas(shown, shift);
        picture.replaceChildren(moved);
        slicer.picture(null, null);
        marks.picture(moved, `${img.chosen}@${shift}`, { always: true });
      }, () => {});
      return;
    }
    const canvas = blank ? blankCanvas(w, hh) : null;
    picture.replaceChildren(shown || canvas
      || (own ? ownModel(p)
        : h('button', { class: 'sv-dropzone', onclick: () => importImages() },
          icon('upload', 'big'),
          h('b', null, 'Drop images here'),
          h('span', null, 'or click to choose · PNG, JPG or WebP'))));
    view.refit();
    slicer.picture(shown, img.chosen || null);
    marks.picture(shown || canvas, img.chosen || (blank ? `blank:${w}x${hh}` : null), { always: blank });
  }

  // ---- right, at the top: Images' own panel (importpanel.js), or the example's slot (Text + Image(s)) ----
  const importPanel = createImportPanel(id);

  // Forge Neo: one example, the pictures start from it (img2img). Qwen-Image 2.1: up to 10 example pictures,
  // shown to it along with the words (its references), in their order.
  const exampleBox = h('div');
  const follow = sliderField('How closely to follow the example', {
    min: 0, max: 0.95, step: 0.05, value: 1 - (s.denoising_strength ?? 0.65),
    format: (v) => (v >= 0.8 ? 'Very closely' : v >= 0.55 ? 'Closely' : v >= 0.3 ? 'Loosely' : 'Very loosely'),
    onInput: (v) => set({ denoising_strength: +(1 - v).toFixed(2) }),
  });
  follow.title = 'Closely keeps the example’s shapes and colours; loosely lets your words change more.';
  const exampleWrap = h('div', { class: 'sv-group' }, exampleBox, follow);
  let adding = 0;   // example pictures on their way to the hub
  const chooseExample = async () => {
    const f = await pickFile(IMAGE_TYPES);
    if (f) replaceExample(f);
  };
  const chooseExamples = async () => addExamples(await pickFiles(IMAGE_TYPES));
  let shownExample = null;
  let exampleTiles = [];   // the example pictures as they show: a Render button "with examples" rings them
  function renderExample(p) {
    const refs = refsOf(p.images);
    const several = controlsOf(backend).has('examples');
    const key = `${backend}|${adding}|${refs.map((r) => boxFile(p, r, 'refs')).join()}`;
    if (key === shownExample) return;
    shownExample = key;
    follow.hidden = !controlsOf(backend).has('follow') || !refs.length;
    const box = several ? examplesList(p, refs) : exampleSlot(p, refs[0] || null);
    exampleBox.replaceChildren(box);
  }

  /** Forge Neo's one example: the slot with it (another one replaces it), or the slot to add it. */
  function exampleSlot(p, ref) {
    const slot = ref
      ? h('div', { class: 'sv-slot filled' },
        h('img', { src: boxFile(p, ref, 'refs'), alt: 'Example image', draggable: 'false' }),
        h('span', null, h('b', null, 'Example'), h('small', null, 'The pictures start from it')),
        h('button', { class: 'icon-btn small', title: 'Use another example', onclick: chooseExample }, icon('upload')),
        h('button', { class: 'icon-btn small', title: 'Remove the example', onclick: () => attempt(() => removeReferences(id)) }, icon('x')))
      : h('button', { type: 'button', class: 'sv-slot', onclick: chooseExample },
        icon('image'), h('span', null, h('b', null, 'Add an example image'), h('small', null, 'Drop it here or click · PNG, JPG or WebP')));
    dropTarget(slot, replaceExample, () => toast(NOT_AN_IMAGE, 'warn'));
    exampleTiles = ref ? [slot] : [];
    return slot;
  }

  /**
   * Qwen-Image 2.1's example pictures: small ones in a row (each with its ×), then a + and "Paste" while there is
   * room; none yet: a wide "Add examples" tile in the same row, so the first picture takes its place without
   * moving what is under it. A pasted one pops in as it appears (popping).
   */
  const popping = new Set();
  function examplesList(p, refs) {
    const thumbs = refs.map((ref, i) => {
      const src = boxFile(p, ref, 'refs');
      const thumb = h('div', {
        class: 'sv-ref',
        onmouseenter: () => { peekImg.src = src; peek.hidden = false; },
        onmouseleave: () => { peek.hidden = true; },
      },
        h('img', { src, alt: `Example ${i + 1}`, draggable: 'false' }),
        h('button', {
          type: 'button', class: 'sv-ref-x', title: 'Remove this example', 'aria-label': `Remove example ${i + 1}`,
          onclick: () => {
            peek.hidden = true;
            attempt(() => removeReferences(id, ref));
          },
        }, icon('x')));
      if (popping.has(ref)) popIn(thumb);
      return thumb;
    });
    exampleTiles = thumbs;
    const room = refs.length < MAX_REFS;
    const add = !room ? null : refs.length ? h('button', {
      type: 'button', class: 'sv-ref sv-ref-add', title: `Add examples (up to ${MAX_REFS} pictures)`, 'aria-label': 'Add examples',
      onclick: chooseExamples, disabled: !!adding,
    }, adding ? spinner() : icon('plus')) : h('button', {
      type: 'button', class: 'sv-ref sv-ref-add sv-ref-first', title: `Add examples (up to ${MAX_REFS} pictures)`,
      onclick: chooseExamples, disabled: !!adding,
    }, adding ? spinner() : icon('image'), h('span', null, h('b', null, 'Add examples'), h('small', null, 'Drag-drop here or click')));
    const paste = room ? h('button', {
      type: 'button', class: 'sv-ref sv-ref-add sv-ref-paste', title: 'Add the picture you copied as an example (Ctrl+V)',
      'aria-label': 'Paste a copied picture', onclick: pasteExamples, disabled: !!adding,
    }, icon('paste'), h('span', null, 'Paste')) : null;
    const el = h('div', { class: 'sv-refs' },
      h('div', { class: 'sv-refs-head' },
        h('span', { class: 'field-label', title: 'The pictures follow their look: the object, its shapes, colours and style. '
          + 'Drop more here.' }, 'Example pictures'),
        h('span', { class: 'sv-refs-count' }, `${refs.length} of ${MAX_REFS}`)),
      h('div', { class: 'sv-refs-row' }, thumbs, add, paste));
    dropTarget(el, addExamples, () => toast(NOT_AN_IMAGE, 'warn'), { all: true });
    return el;
  }

  /** A pasted example picture pops in, once: here is where it went. */
  function popIn(thumb) {
    thumb.animate(fullMotion()
      ? [{ transform: 'scale(0.3)', opacity: 0 },
        { transform: 'scale(1.15)', opacity: 1, boxShadow: '0 0 0 4px rgba(139, 125, 255, 0.7)', offset: 0.55 },
        { transform: 'scale(1)', boxShadow: '0 0 0 0 rgba(139, 125, 255, 0)' }]
      : [{ opacity: 0 }, { opacity: 1, boxShadow: '0 0 0 4px rgba(139, 125, 255, 0.7)' }, { boxShadow: '0 0 0 0 rgba(139, 125, 255, 0)' }],
    { duration: POP_MS, easing: 'ease-out' });
  }

  /** Adds `files` to the example pictures (as many as fit: up to MAX_REFS); pasted ones pop in (`pop`). */
  async function addExamples(files, { pop = false } = {}) {
    const images = files.filter((f) => f.type.startsWith('image/'));
    if (!images.length) {
      if (files.length) toast(NOT_AN_IMAGE, 'warn');
      return;
    }
    const { take, left } = refsToAdd(refsOf(cur().images).length, images);
    if (!take.length) {
      toast(`A prop takes up to ${MAX_REFS} example pictures: remove one to add another.`, 'warn');
      return;
    }
    if (left) toast(`A prop takes up to ${MAX_REFS} example pictures: the first ${take.length} were added.`, 'warn');
    const before = new Set(refsOf(cur().images));
    adding += 1;
    renderExample(cur());
    const ok = await attempt(() => addReferences(id, take).then(() => true));
    adding -= 1;
    const added = ok ? refsOf(cur().images).filter((ref) => !before.has(ref)) : [];
    if (pop) for (const ref of added) popping.add(ref);
    renderExample(cur());
    popping.clear();
    if (added.length) done.push({ kind: 'examples', refs: added, after: viewsNow(), at: undoStamp() });   // Ctrl+Z takes them out
  }

  /** "Paste (Ctrl+V)": the picture on the clipboard joins the example pictures, like a dropped one. */
  async function pasteExamples() {
    let files;
    try {
      files = await clipboardImages();
    } catch (e) {
      // Not allowed, or a browser (or a page not on localhost) without clipboard reading: Ctrl+V still works
      toast(e?.name === 'NotAllowedError' || !navigator.clipboard?.read ? NO_CLIPBOARD : NOTHING_COPIED, 'warn');
      return;
    }
    if (files.length) addExamples(files, { pop: true });
    else toast(NOTHING_COPIED, 'warn');
  }

  // Ctrl+V on the workbench (Render Images): a copied picture becomes an example picture. With the text cursor in a
  // field the paste is the field's own.
  const onPaste = (e) => {
    if (screen !== self || mode !== 'example' || dialogOpen() || isTextField()) return;
    const files = [...(e.clipboardData?.files || [])].filter((f) => f.type.startsWith('image/'));
    if (!files.length) return;
    e.preventDefault();
    if (controlsOf(backend).has('examples')) addExamples(files, { pop: true });
    else replaceExample(files[0]);
  };
  document.addEventListener('paste', onPaste);

  /** Forge Neo's one example: `file` takes the place of the one there was. */
  function replaceExample(file) {
    return attempt(async () => {
      const before = refsOf(cur().images);
      if (before.length >= MAX_REFS) await removeReferences(id);
      await addReferences(id, [file]);
      for (const ref of before) if (refsOf(cur().images).includes(ref)) await removeReferences(id, ref);
    });
  }

  // ---- right: the words, and (Forge Neo) what to avoid ------------------------------------------------
  const prompt = h('textarea', {
    class: 'input sv-prompt', rows: 3, value: s.prompt || '', spellcheck: 'true', 'aria-label': 'Describe the object',
    placeholder: 'Describe one object, e.g. “a weathered wooden barrel with iron bands, hand-painted style”',
  });
  prompt.addEventListener('input', () => set({ prompt: prompt.value }));
  prompt.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' && !e.shiftKey && !e.isComposing) {
      e.preventDefault();
      generate(marks.masked() ? 'viewport' : 'words');
    }
  });
  // Forge Neo's negative prompt. Hidden for Qwen-Image 2.1 (CONTROLS), where it is only kept: nothing is
  // written while it is hidden, so the words are there again when the artist goes back to Forge Neo.
  const negative = h('textarea', {
    class: 'input sv-avoid', rows: 2, value: s.negative_prompt || '', spellcheck: 'true',
    placeholder: 'e.g. blurry, text, watermark, several objects',
  });
  negative.addEventListener('input', () => set({ negative_prompt: negative.value }));
  const avoid = field('Avoid', negative);
  avoid.querySelector('.field-label').title = 'What the pictures should not show';

  // ---- right: model (from the running Forge), shape, variations ---------------------------------------
  const modelSelect = h('select', { class: 'input', 'aria-label': 'Model' });
  let modelValue = s.checkpoint || '';
  modelSelect.addEventListener('change', () => {
    if (modelSelect.value === ADD_MODELS) {
      modelSelect.value = modelValue;
      explainModels();
      return;
    }
    modelValue = modelSelect.value;
    set({ checkpoint: modelValue || null });
  });
  const refreshBtn = h('button', { class: 'icon-btn', title: 'Look for new model files', onclick: () => loadModels(true) }, icon('refresh'));
  const modelNote = h('div', { class: 'hint' });
  const samplerSelect = h('select', { class: 'input', 'aria-label': 'Sampler' });
  samplerSelect.addEventListener('change', () => set({ sampler: samplerSelect.value || null }));
  const schedulerSelect = h('select', { class: 'input', 'aria-label': 'Scheduler' });
  schedulerSelect.addEventListener('change', () => set({ scheduler: schedulerSelect.value || null }));

  const fill = (sel, items, current, autoLabel, extra = []) => {
    sel.replaceChildren(h('option', { value: '' }, autoLabel),
      ...items.map((it) => h('option', { value: it.value, title: it.title }, it.label)), ...extra);
    if (current && !items.some((it) => it.value === current)) sel.insertBefore(h('option', { value: current }, current), extra[0] || null);
    sel.value = current || '';
  };

  let shownModels = null;
  function renderModels() {
    if (backend !== 'forge') {
      modelNote.hidden = true;
      return;
    }
    const m = store.models || {};
    const data = m.state === 'ready' ? m.data : null;
    // No model chosen yet: keep the one Forge shows now (it picks its "current" anew at each start).
    if (data?.current && !settings().checkpoint && data.checkpoints?.some((c) => c.name === data.current)) {
      modelValue = data.current;
      set({ checkpoint: data.current });
    }
    const now = settings();
    // Refilled only when something changed: an open dropdown would close under the artist's pointer.
    const key = JSON.stringify([m.state, m.message, data, now.checkpoint, now.sampler, now.scheduler]);
    if (key === shownModels) return;
    shownModels = key;
    modelValue = now.checkpoint || '';
    // "name" is the stable id: Forge adds " [hash]" to "title" once it has hashed the file.
    const checkpoints = (data?.checkpoints || []).map((c) => ({
      value: c.name || c.title, label: modelLabel(c.name || c.title), title: modelFile(c.name || c.title),
    }));
    fill(modelSelect, checkpoints, now.checkpoint, data?.current ? `Default (${modelLabel(data.current)})` : 'Default model',
      [h('option', { value: ADD_MODELS }, 'Add models…')]);
    const saved = [...modelSelect.options].find((o) => o.value === now.checkpoint);
    if (now.checkpoint && saved && !checkpoints.some((c) => c.value === now.checkpoint)) {
      saved.textContent = data ? `${modelLabel(now.checkpoint)} (not found)` : modelLabel(now.checkpoint);
    }
    fill(samplerSelect, (data?.samplers || []).map((x) => ({ value: x, label: x })), now.sampler, 'Automatic');
    fill(schedulerSelect, (data?.schedulers || []).filter((x) => x !== 'Automatic').map((x) => ({ value: x, label: x })),
      now.scheduler, 'Automatic');
    refreshBtn.disabled = !data;
    modelSelect.title = [modelFile(modelSelect.value === '' ? data?.current || '' : modelSelect.value),
      data ? '' : 'All your models are listed once the image generator has loaded.'].filter(Boolean).join('\n');
    // Only what needs doing is said under the list; the rest is in its tooltip.
    const empty = data && !checkpoints.length;
    modelNote.hidden = !empty && !['loading', 'error'].includes(m.state);
    if (empty) modelNote.replaceChildren('No models yet. ', link('How to add models', explainModels));
    else if (m.state === 'loading') modelNote.textContent = 'Loading the model list…';
    else if (m.state === 'error') modelNote.replaceChildren(`${m.message} `, link('Try again', () => loadModels()));
  }

  const sizeKey = `${s.width || 1024}x${s.height || 1024}`;
  const shapes = SHAPES.map((o) => ({ ...o, label: icon(o.icon) }));
  const shape = segmented(shapes.some((o) => o.value === sizeKey) ? shapes : [...shapes, { value: sizeKey, label: sizeKey.replace('x', '×') }],
    sizeKey, (v) => {
      const [width, height] = v.split('x').map(Number);
      set({ width, height });
      showSizes();
    });
  shape.classList.add('sv-shapes');
  for (const [i, b] of shape.buttons.entries()) b.setAttribute('aria-label', SHAPES[i]?.name || b.textContent);
  // Qwen-Image 2.1: how large the pictures come out, the Shape's sides times 1, 1.5 or 2.
  const resolution = segmented(RESOLUTIONS, s.resolution || 1, (v) => {
    set({ resolution: v });
    showSizes();
  });
  resolution.setAttribute('aria-label', 'Resolution');
  /** Each Resolution says the pixels it gives the Shape picked, each Shape its pixels at the Resolution picked. */
  function showSizes() {
    const now = settings();
    const picked = `${now.width || 1024}x${now.height || 1024}`;
    const factor = controlsOf(backend).has('resolution') ? now.resolution || 1 : 1;
    for (const [i, b] of resolution.buttons.entries()) {
      const { value } = RESOLUTIONS[i];
      b.title = `${sizeAt(picked, value).join(' × ')} pixels`
        + (value > 1 ? `: finer detail; ${value * value} times the pixels of 1K, so it takes longer and needs more video memory` : '');
    }
    for (const [i, b] of shape.buttons.entries()) {
      if (SHAPES[i]) b.title = `${SHAPES[i].name} · ${sizeAt(SHAPES[i].value, factor).join(' × ')}`;
    }
    marks.refit();   // a mask drawn meanwhile: its window is another now
  }
  const count = s.batch_count || 1;
  const variations = segmented([1, 2, 3, 4, ...(count > 4 ? [count] : [])].map((n) => ({ value: n, label: String(n) })), count,
    (v) => { set({ batch_count: v }); syncFoot(); });
  // Qwen-Image 2.1: the object alone, without a background (Pixal3D uses the picture's own transparency).
  const transparent = toggle(s.transparent === true, (v) => set({ transparent: v }), 'Transparent background');
  transparent.title = 'Best for 3D: the object comes out on its own, no background to remove';
  transparent.classList.add('sv-oneline');
  // Qwen-Image 2.1: the First-Block Cache (projects.py first_block_cache). A tick, not a number: the engine
  // decides which steps it applies to. Until the artist sets it (null), the card decides as the launcher does
  // (qwen_server.py FIRST_BLOCK_CACHE_AUTO_BELOW, the same 7.0): ticked on a GTX 10xx (compute capability below
  // 7.0), where a picture takes ~2.5 minutes without it, unticked on newer cards. Read again at every sync: the
  // bench may be built before the hub's first status has said which card it is (syncModel).
  const cacheByCard = () => (store.status?.gpu?.compute_cap ?? 99) < 7.0;
  const firstBlockCache = toggle(typeof s.first_block_cache === 'boolean' ? s.first_block_cache : cacheByCard(),
    (v) => set({ first_block_cache: v }), 'Faster drawing (First-Block Cache)');
  firstBlockCache.title = 'About 35 % faster: on half of the refinement steps the model reuses its middle layers. '
    + 'The same picture with slightly less fine detail; untick for the fullest detail. On by default on GTX 10xx cards.';
  firstBlockCache.classList.add('sv-oneline');
  // Qwen-Image 2.1: a texture that repeats without a seam (projects.py tileable). To judge one, the artist slides
  // it - right and down by tenths of its size, what leaves one side coming back at the other, so its seams cross
  // the picture - and looks at it from afar among copies of itself (the wheel turned on out past the whole picture:
  // picview.js). "R" turns it, to render from it in another direction (rotate).
  const shiftSlider = h('input', {
    type: 'range', class: 'range sv-shift', min: -50, max: 50, step: 10, value: 0, 'aria-label': 'Offset',
    title: 'Offset: slides the picture right and down (to the left: up and left) by tenths of its size, wrapping '
      + 'round, so that its edges meet inside it. Re-Render Viewport then makes pictures from it as it shows.',
  });
  shiftSlider.addEventListener('input', () => {
    shift = +shiftSlider.value / 100;
    syncTiling();
    renderPicture(cur());
  });
  const tileable = toggle(s.tileable === true, (v) => {
    set({ tileable: v });
    syncTiling(v);
    renderPicture(cur());
    marks.refit();
    if (v) showInSide(tileHint);   // the last thing in the list: without this its hint appears out of sight
  }, 'Tileable');
  tileable.title = 'For 2D textures: the picture repeats without a seam, side by side and one above the other';
  tileable.classList.add('sv-oneline');
  let turning = false;          // "R" is at work: one turn at a time
  const turnBtn = h('button', {
    type: 'button', class: 'btn sv-turn', 'aria-label': 'Rotate', onclick: () => rotate(),
    title: 'Rotate: the picture turned a quarter clockwise becomes a new picture of this prop, to render from it in '
      + 'another direction.',
  }, 'R');
  const tileHint = h('div', { class: 'hint' }, 'scrollwheel on canvas to zoom out');
  const tileBox = h('div', { class: 'sv-tileable' },
    h('div', { class: 'sv-tileable-row' }, tileable, turnBtn, shiftSlider), tileHint);
  /**
   * What Tileable shows while it is on (`on`: as just set, else as the prop has it, for a model that draws such
   * pictures): "R" (while there is a picture to turn), the offset slider and the hint under the tick, and - once the
   * wheel was turned on out past the whole picture - the picture a quarter its size among copies of itself. Off, the
   * picture is back as it is.
   */
  const tilingOn = () => tileable.input.checked && !tileBox.hidden;
  function syncTiling(on = tilingOn()) {
    if (!on) {
      shift = 0;
      view.afar = false;
      shiftSlider.value = 0;
    }
    shiftSlider.hidden = turnBtn.hidden = tileHint.hidden = !on;
    turnBtn.disabled = turning || !cur().images?.chosen;
    tiling.hidden = !on || !cur().images?.chosen;
    tiling.style.setProperty('--shift', String(wrapped(shift)));
    stageEl.classList.toggle('afar', view.afar && !tiling.hidden);
  }

  // The built-in image generator: which of its models draws this prop (QWEN_MODELS; projects.py qwen_model), under
  // its name. While the full model or FLUX.3 is not on disk, its button does not pick it: it starts its download (the
  // hub opens its folder in File Explorer) and says how far it got, with a bar under the choice; once it is there it
  // is a choice like Turbo. FLUX.3's button is disabled while the image engine cannot draw it (its note and tooltip
  // say so). With Turbo or FLUX.3 picked, Steps and "Faster drawing" hide (shownControls): each has its own steps;
  // with FLUX.3 "Transparent background" too (it draws opaque pictures).
  // The full model's button says the steps its slider under More is at (Turbo and FLUX.3 are distilled for theirs).
  const modelNotes = [];
  let fullName = null;
  const modelSeg = segmented(QWEN_MODELS.map((m) => {
    const note = h('small', { class: 'sv-model-note', hidden: true });
    modelNotes.push(note);
    const name = h('span', { class: 'sv-model-name' }, m.label);   // its brackets on a line of their own
    if (m.value === 'full') fullName = name;
    const label = h('span', { class: 'sv-model-text' }, name, note);
    return { value: m.value, title: m.title, label };
  }), qwenModelOf(s), (v) => pickModel(v));
  const showFullSteps = (n) => { fullName.textContent = `Full\n(${n} steps)`; };
  modelSeg.setAttribute('aria-label', 'Image model');
  const modelBar = progressBar(null);
  const modelError = h('div', { class: 'hint sv-model-error', hidden: true });
  const modelBox = h('div', { class: 'sv-model' }, modelSeg, modelBar, modelError);
  const asking = new Set();   // the models whose download the hub has not started yet: a double click asks once
  const stateOf = (model) => optionalModelState(model, store.status?.[OPTIONAL_MODELS[model].status]);

  function pickModel(v) {
    const state = OPTIONAL_MODELS[v] ? stateOf(v).state : 'available';
    if (state !== 'available' && state !== 'unknown') {
      modelSeg.set(qwenModelOf(settings()));   // the prop stays on its model until this one is there (and drawable)
      if (state !== 'unsupported') getModel(v);
      return;
    }
    set({ qwen_model: v });
    syncModel();
    warmPicked(v);
  }

  async function getModel(model) {
    if (asking.has(model)) return;
    asking.add(model);
    await attempt(() => downloadModel(model));
    asking.delete(model);
    syncModel();
  }

  /** The model choice as the prop and the hub have it, the downloads' state on their buttons, and each model's own
   * controls only with it. */
  function syncModel() {
    const model = qwenModelOf(settings());
    modelSeg.set(model);
    const states = {};
    for (const [i, m] of QWEN_MODELS.entries()) {
      if (!OPTIONAL_MODELS[m.value]) continue;
      const st = stateOf(m.value);
      states[m.value] = st;
      const [btn, note] = [modelSeg.buttons[i], modelNotes[i]];
      const offer = st.state === 'missing' || st.state === 'failed';
      btn.classList.toggle('sv-get', offer);
      btn.disabled = st.state === 'unsupported';
      btn.title = st.title;
      note.hidden = !st.note;
      note.replaceChildren(...(offer ? [icon('download'), st.note] : [st.note]));
    }
    const going = Object.values(states).find((st) => st.state === 'downloading');
    modelBar.hidden = !going;
    modelBar.set(going ? going.fraction : null);
    const failed = Object.values(states).filter((st) => st.state === 'failed');
    modelError.hidden = !failed.length;
    modelError.textContent = failed.map((st) => st.title).join(' ');   // the hub's words name the model
    showFullSteps(settings().qwen_steps ?? QWEN_STEPS);
    const cache = settings().first_block_cache;
    firstBlockCache.input.checked = typeof cache === 'boolean' ? cache : cacheByCard();
    const shown = shownControls(backend, model);
    const own = [['qwenSteps', qwenSteps], ['firstBlockCache', firstBlockCache], ['transparent', transparent],
      ['tileable', tileBox], ['qwenModel', modelBox]];
    for (const [name, part] of own) part.hidden = !shown.has(name);
    syncTiling();
    renderToolRow();
  }

  /** The controls show the prop's settings again (a picture's own came back: pick). */
  function showSettings() {
    const now = settings();
    prompt.value = now.prompt || '';
    negative.value = now.negative_prompt || '';
    shape.set(`${now.width || 1024}x${now.height || 1024}`);
    resolution.set(now.resolution || 1);
    showSizes();
    variations.set(now.batch_count || 1);
    transparent.input.checked = now.transparent === true;
    steps.set(now.steps ?? 25);
    qwenSteps.set(now.qwen_steps ?? QWEN_STEPS);
    cfg.set(now.cfg_scale ?? 6);
    seed.firstChild.value = (now.seed ?? -1) >= 0 ? String(now.seed) : '';
    shownModels = null;
    renderModels();
    syncModel();
    syncFoot();
  }

  // Qwen-Image 2.1, in the model list's place: its name, and the chip of its licence, which shows the line
  // with the links (licenses.js) - FLUX.3 Image Klein's name and licence while that model is picked.
  const toolRow = h('div', { class: 'sv-inline-field sv-tool-row' });
  const terms = h('div', { class: 'sv-terms', hidden: true });
  let shownTool = null;       // what the row shows ("<generator>:<licence's owner>:<size>"): rebuilt only when that changes
  function renderToolRow() {
    const flux3 = qwenModelOf(settings()) === 'flux3';
    const licensed = backend === 'qwen' && flux3 ? 'flux3' : backend;
    const key = `${backend}:${licensed}:${store.status?.config?.quality || ''}`;
    if (key === shownTool) return;
    shownTool = key;
    terms.hidden = true;
    terms.replaceChildren();
    if (!controlsOf(backend).has('tool')) return;
    const quality = store.status?.config?.quality;
    const chip = licenseChip(licensed, () => {
      terms.hidden = !terms.hidden;
      terms.replaceChildren(terms.hidden ? '' : licenseLine(licensed, { showFile: showConfigFile }) || '');
      chip.setAttribute('aria-expanded', String(!terms.hidden));
      chip.classList.toggle('on', !terms.hidden);
    });
    const size = quality ? `. Model size ${quality} (spellcast3d-config.ini; a bigger size already in the models folder is used instead)` : '';
    toolRow.replaceChildren(h('span', { class: 'field-label' }, 'Model'),
      h('span', {
        class: 'sv-tool-name',
        title: licensed === 'flux3' ? `Black Forest Labs’ model, drawn by Spellcast3D’s built-in engine${size}.`
          : `Built into Spellcast3D${size}.`,
      }, licensed === 'flux3' ? 'FLUX.3 Image Klein' : toolName(backend)),
      chip);
  }

  // More
  const steps = sliderField('Steps', {
    min: 1, max: 60, step: 1, value: s.steps ?? 25, onInput: (v) => set({ steps: v }),
    hint: 'More steps add detail but take longer. Fast “Lightning” / “Turbo” models need 4-8.',
  });
  const qwenSteps = sliderField('Steps', {
    min: 1, max: 60, step: 1, value: s.qwen_steps ?? QWEN_STEPS,
    onInput: (v) => {
      set({ qwen_steps: v });
      showFullSteps(v);
    },
    hint: QWEN_STEPS_HINT,
  });
  const cfg = sliderField('Guidance (CFG)', {
    min: 1, max: 15, step: 0.1, value: s.cfg_scale ?? 6, format: (v) => v.toFixed(1), onInput: (v) => set({ cfg_scale: v }),
    hint: 'How strictly the picture follows your words. 5-7 suits most models, 1-2 the fast ones.',
  });
  const samplers = h('div', { class: 'sv-grid2' }, field('Sampler', samplerSelect), field('Scheduler', schedulerSelect));
  const seed = seedInput(s.seed ?? -1, (v) => set({ seed: v }), { max: MAX_SEED });
  const fastImages = fasterSwitch('images');     // the hub's, for every prop (faster.js)
  const more = h('details', { class: 'fold' },
    h('summary', null, 'More'),
    h('div', { class: 'sv-group' },
      rowField('Shape', shape),
      rowField('Variations', variations),
      steps, qwenSteps, cfg,
      samplers,
      rowField('Seed', seed, 'Empty: a new surprise each time. A number repeats a result.'),
      transparent, tileBox));

  const modelRow = h('div', { class: 'sv-inline-field' }, h('span', { class: 'field-label' }, 'Model'),
    h('div', { class: 'sv-with-btn' }, modelSelect, refreshBtn));
  const resolutionRow = rowField('Resolution', resolution);
  // The words, with "+prompt" and the shown prompts of the library at their bottom.
  const promptChips = promptBar(prompt, () => library.open());
  const promptBox = h('div', { class: 'sv-prompt-box' }, prompt, promptChips);
  const genPanel = h('div', { class: 'sv-group' },
    promptBox,
    avoid,
    modelRow,
    modelNote,
    toolRow,
    terms,
    modelBox,
    resolutionRow,
    fastImages,
    firstBlockCache,
    more);

  // The controls only one image generator has (CONTROLS); the example's are in renderExample.
  const parts = {
    avoid: [avoid], model: [modelRow], tool: [toolRow], steps: [steps], qwenSteps: [qwenSteps], cfg: [cfg], sampler: [samplers],
    transparent: [transparent], tileable: [tileBox], firstBlockCache: [firstBlockCache], fastImages: [fastImages],
    qwenModel: [modelBox],
    resolution: [resolutionRow],
  };

  /** Shows the controls of the image generator spellcast3d-config.ini picks (the hub says which). */
  function syncBackend() {
    const tool = imageTool();
    if (tool === backend) return;
    backend = tool;
    const shown = controlsOf(tool);
    for (const [name, els] of Object.entries(parts)) for (const part of els) part.hidden = !shown.has(name);
    prompt.classList.toggle('alone', !shown.has('avoid'));   // no "Avoid" under it: the words take its room
    marks.selectable(tool !== 'forge');                     // Select Object speaks to Qwen-Image's editing
    const words = modesFor(tool);
    for (const [i, b] of modeSeg.buttons.entries()) {
      b.title = words[i].title;
      b.textContent = words[i].label;
    }
    showSizes();
    renderToolRow();
    syncModel();
    shownExample = null;
    shownModels = null;
  }

  // Foot: the three buttons that make pictures, in one row - "Render From Scratch" (from the words and the example
  // pictures, never the viewport) and "Re-Render Viewport" (from what the viewport shows, with its marks), "no
  // examples" or "with examples" under each -, then the tool's state and the last error.
  const genCount = h('span', { class: 'sv-count' });
  const genSub = h('small');
  const makes = [
    ['words', 'sv-render', 'Render\nFrom Scratch', genSub],
    ['viewport', 'sv-rerender', 'Re-Render Viewport', h('small', null, 'no examples')],
    ['viewport+examples', 'sv-rerender', 'Re-Render Viewport', h('small', null, 'with examples')],
  ].map(([kind, cls, name, sub]) => {
    const label = h('span', null, name);
    const btn = h('button', { type: 'button', class: `btn sv-make ${cls}`, onclick: () => generate(kind) },
      h('b', null, label, kind === 'words' && genCount), sub);
    return { kind, name, label, btn };
  });
  const [genBtn, viewportBtn, viewportExBtn] = makes.map((m) => m.btn);
  // The pointer on a Render button rings the Resolution once: what the pictures are about to be rendered at; on one
  // "with examples", the example pictures too: which ones go along.
  for (const { kind, btn } of makes) {
    btn.addEventListener('pointerenter', () => {
      if (!resolutionRow.hidden) ring(resolution);
      if (kind === 'viewport+examples' || (kind === 'words' && refsOf(cur().images).length)) exampleTiles.forEach((t) => ring(t));
    });
  }
  const makeRow = h('div', { class: 'sv-makes' }, genBtn, viewportBtn, viewportExBtn);
  let started = null;   // which of them started the prop's job ('words', 'viewport', 'viewport+examples')
  const gate = gateLine('images', {
    installing: 'Generate waits for it; importing images works already.', config: 'Importing images works without it.',
  });
  const error = errorLine('images');
  const foot = h('div', { class: 'sv-foot' }, error, gate, makeRow);

  const sideList = h('div', { class: 'sv-side-scroll' }, importPanel.el, exampleWrap, genPanel);
  const side = h('div', { class: 'sv-side' }, sideList, foot);

  /** The side list scrolls on, as far as it takes, until `shown` stands whole above the list's fading bottom edge. */
  function showInSide(shown) {
    const under = shown.getBoundingClientRect().bottom + SIDE_FADE - sideList.getBoundingClientRect().bottom;
    if (under > 0) sideList.scrollBy?.({ top: under, behavior: fullMotion() ? 'smooth' : 'auto' });
  }

  const el = h('div', { class: 'sv sv-images' }, head, media, side);

  /**
   * The mode `v` shows: what the side panel holds for it (Images: its own panel alone; Render Images: the example
   * pictures, the words and the settings). A new mode adds its panel to `side` above and its line here.
   */
  function setMode(v) {
    mode = v;
    modes.set(id, v);
    modeSeg.set(v);
    importPanel.el.hidden = v !== 'import';
    exampleWrap.hidden = v !== 'example';
    genPanel.hidden = v === 'import';
    renderPicture(cur());
    syncMarks();
    syncFoot();
  }

  /**
   * The markers show on Render Images while a picture or the black canvas shows there and none is being made - not
   * while a tileable picture is looked at from afar.
   */
  function syncMarks() {
    syncTiling();
    marks.show(mode === 'example' && (!!cur().images?.chosen || blank) && !jobFor('images', id)
      && !stageEl.classList.contains('afar'));
  }

  function syncFoot() {
    const j = jobFor('images', id);
    const p = cur();
    const gen = mode !== 'import';
    const n = settings().batch_count || 1;
    const refs = refsOf(p.images).length > 0;
    const viewport = !!p.images?.chosen || blank;   // a picture, or the black canvas, to re-render
    if (!j) started = null;
    const runs = (kind) => !!j && (started || 'words') === kind;
    const busyWord = j?.phase === 'running' ? 'Rendering…' : 'Waiting…';
    // The three always look alike; the one whose job runs says so and stays bright.
    for (const m of makes) {
      m.label.textContent = runs(m.kind) ? busyWord : m.name;
      m.btn.classList.toggle('working', runs(m.kind));
    }
    genCount.textContent = n > 1 && !runs('words') ? ` ×${n}` : '';
    genCount.hidden = !genCount.textContent;
    genSub.textContent = refs ? 'with examples' : 'no examples';
    genBtn.hidden = !gen;
    const shut = !!j || !gateOpen(toolGate('images'));   // while it installs, the job waits for it
    // A mask on the picture: From Scratch waits; a mask too large is not sent, and the viewport's buttons say why.
    const mask = marks.masked();
    genBtn.disabled = shut || !!mask;
    genBtn.title = mask ? 'A mask is on the picture: Re-Render Viewport changes what it covers (Esc takes it off)' : '';
    const tooLarge = mask?.tooLarge ? MASK_TOO_LARGE : '';
    viewportBtn.hidden = viewportExBtn.hidden = mode !== 'example';
    viewportBtn.disabled = shut || !viewport;
    viewportBtn.title = tooLarge || (mask ? 'New pictures with what you masked changed as your words say'
      : 'New pictures from what the viewport shows, with the marks you painted on it, and your words');
    const forge = backend === 'forge';   // Forge Neo starts from one picture: the viewport's
    viewportExBtn.disabled = shut || !viewport || !refs || forge;
    viewportExBtn.title = forge ? 'Forge Neo starts from one picture: use Re-Render Viewport'
      : !refs ? 'Add examples first'
        : tooLarge || 'New pictures from what the viewport shows (with its marks), your words and the example pictures';
    gate.sync();
    gate.hidden ||= !gen || !!j;   // with a job of its own, the layer over the picture says it
    error.sync(cur());
    foot.hidden = !gen && error.hidden;   // Import has no button down here
  }

  /**
   * A job for this prop from its saved settings, with what the button (`kind`: 'words', 'viewport',
   * 'viewport+examples') adds for this one job (`params`: whether the example pictures go along, and the picture in
   * the viewport before them). `select` (Select Object): {prompt, picture()} in place of the words and the marks.
   * With Smart Mask's mask on the picture, the viewport's buttons send the picture under the mask, the mask alone and
   * the words as maskedPrompt has them.
   */
  async function generate(kind = 'words', select = null) {
    if (mode === 'import') return;
    const p = cur();
    const viewport = mode === 'example' && kind !== 'words';
    const masking = select ? null : marks.masked();
    if (jobFor('images', id) || !gateOpen(toolGate('images')) || (masking && !viewport)) return;
    if (viewport && ((!p.images?.chosen && !blank) || (kind === 'viewport+examples' && !refsOf(p.images).length))) return;
    const words = settings().prompt?.trim();
    if (!select && !words) {
      toast(masking ? 'Say in a few words what should be in the masked area first.'
        : viewport ? 'Say in a few words what to change, or what you painted, first.'
          : 'Describe the object first: a few words are enough.', 'warn');
      prompt.focus();
      (masking ? ripple : ring)(promptBox);
      return;
    }
    if (masking?.tooLarge) {
      toast(MASK_TOO_LARGE, 'warn');
      return;
    }
    genBtn.disabled = viewportBtn.disabled = viewportExBtn.disabled = true;
    if (!select) circling = null;   // its pictures are not of a circled object
    if (masking) select = { prompt: maskedPrompt(words), picture: masking.picture, mask: masking.mask };
    const params = {};
    if (viewport) {
      // The picture with its marks is uploaded first (the black canvas always; a picture without marks the hub reads
      // itself).
      // Smart Mask over one of the prop's pictures: its mask goes up too, and the job names that picture - what
      // is made is brought back to its tone, and a tileable one is kept, to the pixel, outside the change.
      const maskOf = !!select?.mask && !!p.images?.chosen;
      const from = await attempt(async () => {
        const png = await (select ? select.picture() : marks.composite());
        return png ? saveViewport(id, png, maskOf ? await select.mask() : null) : p.images?.chosen;
      });
      if (!from) {
        syncFoot();
        return;
      }
      params.from_viewport = from;
      params.use_references = kind === 'viewport+examples';
      if (select) params.prompt = select.prompt;
      // A tileable picture goes up as the offset slider shows it; what is made from it is laid back where this one
      // lies - the hub slides it back as far, and onto it to the pixel (the model lays a tileable picture some pixels
      // off) -, so the slider shows both alike. Not a circled object's picture: it is the object alone, placed anew.
      if (tilingOn() && p.images?.chosen && !circling) params.viewport_shift = shift;
      if (maskOf) params.viewport_mask_of = p.images.chosen;
    } else if (refsOf(p.images).length && settings().use_references === false) {
      params.use_references = true;   // a prop saved by an older version with its example pictures left out
    }
    started = viewport ? kind : 'words';
    const going = await attempt(() => startJob('images', [id], { params: Object.keys(params).length ? params : null })
      .then(() => true));
    if (going && masking) marks.unmask();   // sent: the mask goes with its picture
    syncFoot();
  }

  /**
   * "R": the chosen picture, turned a quarter clockwise, becomes a new picture of the prop and its chosen one (the one
   * it was turned from stays in the row). A Shape that fits the picture turns with it, so a render from the turned
   * picture has its shape.
   */
  async function rotate() {
    const p = cur();
    const path = p.images?.chosen;
    if (!path || turning) return;
    turning = true;
    syncTiling();
    await attempt(async () => {
      const { png, width, height } = await quarterTurned(boxFile(p, path, 'images'));
      const now = settings();
      const shaped = [now.width || 1024, now.height || 1024];
      await uploadImages(id, [new File([png], 'rotated.png', { type: 'image/png' })]);
      if (width !== height && sameShape([height, width], shaped)) {
        set({ width: shaped[1], height: shaped[0] });
        shape.set(`${shaped[1]}x${shaped[0]}`);
        showSizes();
      }
    });
    turning = false;
    syncTiling();
  }

  /**
   * The picture `path` carried onto the props column: a new prop with it as its picture (this prop keeps it too),
   * named after the object circled to make it, else after this prop with the next free number; its tile rings.
   */
  async function promote(path) {
    const p = cur();
    if (!path || !p.images?.candidates?.includes(path)) return;
    const circled = circledIn.get(path);
    const base = circled ? circled[0].toUpperCase() + circled.slice(1) : p.name || 'Prop';
    const taken = new Set((store.project?.props || []).map((x) => x.name));
    let name = circled && !taken.has(base) ? base : null;
    for (let n = 2; !name; n += 1) if (!taken.has(`${base} ${n}`)) name = `${base} ${n}`;
    await attempt(async () => {
      const got = await fetch(boxFile(p, path, 'images'));
      if (!got.ok) throw new Error('That picture could not be read. Reload the page and try again.');
      const blob = await got.blob();
      const made = await addProp(name);
      await uploadImages(made.id, [new File([blob], 'picture.png', { type: blob.type || 'image/png' })]);
      emit('pulse-prop', { id: made.id });
      toast(`“${name}” is a prop of its own now.`, 'success', 2250);
    });
  }

  /**
   * Imports the pictures `files` (else the ones the artist chooses) in one go. One picture becomes the
   * chosen one. Two or more become the object's sides (slicer.importSides: the ones their file names say,
   * the others in name order - the order a file picker or a drag gives them is not the artist's), the front
   * one chosen; the views they replace come back with Ctrl+Z.
   */
  async function importImages(files) {
    const given = files || await pickFiles(IMAGE_TYPES);
    const images = given.filter((f) => f.type.startsWith('image/'));
    if (!images.length) {
      if (given.length) toast(NOT_AN_IMAGE, 'warn');
      return;
    }
    if (images.length > MAX_IMPORT) {
      toast(`These are too many pictures at once. Import at most ${MAX_IMPORT}.`, 'warn');
      return;
    }
    const plan = importSides(images.map((f) => f.name || ''));
    const ordered = plan.map((x) => images[x.index]);
    const sides = plan.map((x) => x.side);
    const before = cur().images || {};
    const hadViews = before.views?.length ? { views: before.views, chosen: before.chosen } : null;
    // A quick upload shows nothing; a slow one its progress, after a moment.
    const what = `Uploading ${plural(images.length, 'picture')}…`;
    uploads += 1;
    const showSoon = setTimeout(() => { uploading.hidden = false; }, 300);
    const progress = (f) => {
      uploadText.textContent = f == null || f >= 1 ? what : `${what} ${Math.round(f * 100)}%`;
      uploadBar.set(f == null || f >= 1 ? null : f);
    };
    progress(null);
    // The draft becomes a prop with them, named (unless the artist named it) after its words or the first file.
    const ok = await attempt(() => uploadImages(id, ordered, progress, images.length > 1 ? sides : null).then(() => true));
    clearTimeout(showSoon);
    uploads -= 1;
    if (!uploads) uploading.hidden = true;
    if (!ok) return;
    if (mode !== 'import' && !settings().prompt?.trim()) setMode('import');
    if (images.length < 2 || !sides.some(Boolean)) return;
    if (hadViews) slicer.remember(hadViews.views, hadViews.chosen);
    // Which picture became which side, when the names did not say it all (or earlier views were replaced).
    const guessed = plan.some((x) => x.side && !x.told);
    const mv = store.status?.multiview;
    const frontOnly = !!mv && !mv.available && sides.filter(Boolean).length >= 2;
    if (!guessed && !hadViews && !frontOnly) return;
    const said = plan.filter((x) => x.side).map((x) => `${VIEWS[x.side].label}: ${images[x.index].name}`).join(' · ');
    toast([`${said}.`,
      guessed ? 'Taken in name order where the file names don’t say the side: click a view’s label on the picture to change it.' : '',
      hadViews ? 'Ctrl+Z brings back the views it had before.' : '',
      frontOnly ? 'Until the multi-view models are downloaded (the 3D stage offers them), the Front view alone is made into 3D.' : '',
    ].filter(Boolean).join(' '), 'info', 9000);
  }

  const self = {
    id, el, kind: 'bench', draft: !!prop.draft,
    // What the chooser's morph animates: the mode buttons it flies into, and what fades in around them.
    modeSeg, modeButtons: modeSeg.buttons, body: [media, side],
    importImages,
    update(p) {
      self.draft = !!p.draft;
      renderStrip(p);   // first: the mark of the chosen picture never waits for the rest
      syncBackend();
      syncModel();      // the model downloads' state and the card's defaults, as the status poll brings them
      renderPicture(p);
      syncMarks();
      importPanel.update();
      renderExample(p);
      busy.sync(p);
      renderLive();
      slicer.update({ busy: !!jobFor('images', id) });
      syncFoot();
      renderModels();
    },
    /** Right after the way was picked on the chooser: Render asks for the words (Images' panel says the rest). */
    begin() {
      if (mode !== 'import') prompt.focus({ preventScroll: true });
    },
    /** "+ New prop" while this empty draft shows: the place to start says "here". */
    nudge() {
      const target = mode === 'import' ? importPanel.el : prompt;
      if (target === prompt) prompt.focus({ preventScroll: true });
      target.scrollIntoView({ block: 'nearest' });
      pulse(target);
    },
    destroy() {
      clearTimeout(liveGone);
      liveUrl = '';   // a preview still loading is not shown
      document.removeEventListener('paste', onPaste);
      document.removeEventListener('keydown', onUndo, true);
      dropUndo();
      view.destroy();
      marks.destroy();
      promptChips.destroy();
      library.destroy();
      importPanel.destroy();
      slicer.destroy();
    },
  };
  setMode(mode);
  self.update(prop);
  return self;
}

const link = (text, fn) => h('a', { href: '#', onclick: (e) => { e.preventDefault(); fn(); } }, text);

/** The black canvas Render Images shows until there is a picture: `w` x `h`, for the markers to paint on. */
/** A shift as the part of the picture that comes back in at its left and top (0 .. 1, in thousandths). */
const wrapped = (shift) => Math.round((((shift % 1) + 1) % 1) * 1000) / 1000;

/**
 * `image` moved by `shift` of its size to the right and down (negative: left and up), what leaves one side coming
 * back at the other, as Photoshop's Offset does: a canvas of its size that stands in for it.
 */
export function shiftedCanvas(image, shift) {
  const [w, hh] = [image.naturalWidth, image.naturalHeight];
  const canvas = h('canvas', { class: 'sv-picture-img' });
  canvas.width = w;
  canvas.height = hh;
  const g = canvas.getContext?.('2d');
  const [dx, dy] = [Math.round(wrapped(shift) * w), Math.round(wrapped(shift) * hh)];
  for (const [x, y] of [[dx - w, dy - hh], [dx, dy - hh], [dx - w, dy], [dx, dy]]) g?.drawImage(image, x, y);
  return canvas;
}

function blankCanvas(w, hh) {
  const canvas = h('canvas', { class: 'sv-picture-img sv-blank' });
  canvas.width = w;
  canvas.height = hh;
  canvas.setAttribute('aria-label', 'An empty black canvas: paint on it, then Re-Render Viewport');
  const g = canvas.getContext?.('2d');
  if (g) {
    g.fillStyle = '#000';
    g.fillRect(0, 0, w, hh);
  }
  return canvas;
}

/** What the picture area shows for a prop made from the artist's own 3D model (it needs no picture). */
function ownModel(prop) {
  const file = (prop.mesh.source || '').split('/').pop();
  const snap = thumbUrl(prop, 'mesh');
  return h('div', { class: 'sv-empty sv-own-model' },
    snap ? h('img', { src: snap, alt: '', draggable: 'false' }) : icon('cube', 'big'),
    h('h3', null, 'This prop is your own 3D model'),
    h('p', null, file ? `Imported from ${file}. It needs no picture to go on.` : 'It needs no picture to go on.'),
    h('div', { class: 'sv-empty-actions' },
      h('button', { class: 'btn ghost', onclick: () => ctx?.goto('mesh') }, icon('cube'), 'Go to 3D')),
    h('p', { class: 'hint' }, 'You can still give it a picture: import or describe one on the right.'));
}

/** "Add models…": where image models go and how they show up here. */
function explainModels() {
  modal({
    title: 'Add image models',
    body: h('div', { class: 'stack sv-explain' },
      h('p', { class: 'modal-text' }, 'The image generator uses Stable Diffusion models: large .safetensors files, for example '
        + 'an SDXL checkpoint from a model site.'),
      h('ol', { class: 'sv-steps' },
        h('li', null, 'Put the file into the ', h('b', null, 'models\\checkpoints'), ' folder of your Spellcast3D folder '
          + '(the button below opens it).'),
        h('li', null, 'Press ', h('b', null, '↻'), ' next to the model list, or wait for the next start of the image generator.'),
        h('li', null, 'Pick it in the list.')),
      h('p', { class: 'hint' }, 'VAE files go into models\\vae, text encoders into models\\text-encoders and LoRAs into models\\loras. '
        + 'Models you keep in another folder can be used without copying them: Settings > Advanced > Extra model folders.')),
    actions: [
      { label: 'Close', value: false },
      {
        label: 'Open the models folder', kind: 'primary',
        onclick: (close) => { attempt(() => api('POST', '/api/open-folder', { which: 'forge_models' })); close(true); },
      },
    ],
  });
}

// ---- the draft ------------------------------------------------------------------------------------

let draftRequest = null;
let draftError = null;   // why the hub gave no draft (shown with "Try again" instead of retrying on every update)

/**
 * The project's draft: asked from the hub when the store has none (the hub makes one, with the stage
 * settings of the last prop). Several calls at once share one request.
 */
function ensureDraft() {
  if (draftOf()) return Promise.resolve(draftOf());
  const pid = projectId();
  draftRequest ||= api('POST', `${projectApi(pid)}/draft`).then((prop) => {
    if (projectId() === pid && !draftOf()) {
      store.project.props.push(prop);
      emit('project', { hard: true });
    }
    return prop;
  }).finally(() => { draftRequest = null; });
  return draftRequest;
}

/**
 * The next draft while `draft`'s first pictures are still being made: the hub makes `draft` a prop (the
 * pictures fill it when they arrive) and gives a new, empty draft. A hub that keeps a busy draft refuses.
 */
async function nextDraft(draft) {
  const pid = projectId();
  const fresh = await api('POST', `${projectApi(pid)}/draft`);
  if (fresh.id === draft.id) throw new ShellRefusal(ON_ITS_WAY);
  if (screen?.id === draft.id) screen.draft = false;   // it goes on as a prop in the list; the workbench moves on
  if (projectId() === pid) await reloadProject();
  return fresh;
}

// ---- the stage view -----------------------------------------------------------------------------

function show(next) {
  screen?.destroy();
  screen = next;
  root.replaceChildren(next.el);
  fadeIn(next.el);
}

function render() {
  if (!host) return;
  const prop = boundProp();
  if (!prop) {
    if (!draftError) {
      ensureDraft().catch((e) => {
        draftError = e.message;
        render();
      });
      if (screen) return;   // the draft is on its way: what shows stays until it is here
    }
    screen?.destroy();
    screen = null;
    const retry = h('button', { class: 'btn ghost', onclick: () => { draftError = null; render(); } }, icon('refresh'), 'Try again');
    root.replaceChildren(h('div', { class: 'sv-preparing' }, draftError
      ? emptyState('alert', 'The workbench could not be prepared', draftError, retry)
      : emptyState(null, 'Preparing your workbench…')));
    return;
  }
  if (!prop.draft) {
    lastShown = prop.id;
    // The draft on screen has just become this prop (its first picture): the column selects it too.
    if (ctx.selectedId !== prop.id && adopting !== prop.id) {
      adopting = prop.id;
      ctx.select(prop.id);
    }
  }
  const kind = choosing(prop) ? 'chooser' : 'bench';
  if (screen?.id === prop.id && screen.kind === kind) {
    screen.update(prop);
    return;
  }
  show(kind === 'chooser' ? buildChooser(prop) : buildBench(prop));
}

export default {
  id: 'images',
  title: 'Images',
  ctaLabel: 'Generate 3D',
  ctaHover: 'Loads 3D-generation neural nets, so you can create 3D models for all the images in one pass.',
  plus: 'new',
  warmWish: () => warmWish(),

  mount(el, c) {
    host = el;
    adopting = null;
    const id = entryId(c);
    ctx = { ...c, selectedId: id };
    if ((c.selectedId || null) !== id) c.select(id);
    root = h('div', { class: 'sv-imgroot' });
    host.replaceChildren(root);
    render();
    wantModels();
  },

  update(c) {
    ctx = c;
    if (!host) return;
    render();
    wantModels();
  },

  unmount() {
    screen?.destroy();
    screen = null;
    root = null;
    host = null;
  },

  status(prop) {
    return jobState('images', prop)
      || (prop.images?.chosen ? { state: 'done', message: 'Has its picture' }
        : prop.mesh?.imported ? { state: 'done', message: 'Your own 3D model' }
          : { state: 'idle', message: 'No picture yet' });
  },

  /** The prop on the workbench: the one selected in the column, or the draft. */
  shownId: () => screen?.id ?? null,

  ctaEnabled() {
    if (boxesOf().some((p) => p.images?.chosen || p.mesh?.glb)) return { enabled: true };
    const making = [draftOf(), ...boxesOf()].some((p) => p && jobFor('images', p.id));
    return { enabled: false, hint: making ? ON_ITS_WAY : NO_IMAGE };
  },

  /** Queues a 3D model for every prop without a fresh one (the shell then goes down to 3D). */
  async onCta() {
    await carryDown('mesh');
  },

  /**
   * "+ New prop": the draft, the next prop (an empty one offers the three ways again). Already on screen:
   * the place to start pulses. A draft whose first pictures are being made becomes a prop first.
   */
  async onPlus(c) {
    let draft = draftOf() || await ensureDraft();
    if (jobFor('images', draft.id)) draft = await nextDraft(draft);
    if (screen?.id === draft.id && !findBox(c.selectedId)) {
      screen.nudge();
      return;
    }
    if (!draft.images?.settings?.prompt?.trim() && !refsOf(draft.images).length) modes.delete(draft.id);
    adopting = null;
    if (c.selectedId) c.select(null);
    else {
      ctx = { ...ctx, selectedId: null };
      render();
    }
  },
};
